import sys, json

data = json.load(sys.stdin)
json.dump(data, open('after-cpm-packages.json', 'w'), indent=2)

# Compare with baseline
baseline = json.load(open('baseline-packages.json'))

print('=== Package Comparison ===')
def get_packages(d):
    result = {}
    for proj in d['projects']:
        pname = proj['path'].split('/')[-2]
        for fw in proj['frameworks']:
            key = f\"{pname}/{fw['framework']}\"
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(key, {})[pkg['id']] = pkg['resolvedVersion']
    return result

b = get_packages(baseline)
a = get_packages(data)

changes = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(key, {})
    ap = a.get(key, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av:
            changes.append(f'  {key}: {pkg} {bv} -> {av}')

if changes:
    print('CHANGES:')
    for c in changes:
        print(c)
else:
    print('No version changes detected - conversion is version-neutral!')
